import gc
import inspect
import io
from concurrent.futures import ThreadPoolExecutor

import matplotlib

matplotlib.use("Agg")  # headless backend; Streamlit renders figures itself

import matplotlib.pyplot as plt
import networkx as nx
import PIL.Image
import streamlit as st
import sympy as sp
from ket import CZ, H, Quant, X, around, cat, gateset, qulib
from sympy import I, Matrix, cos, exp, eye, sin
from sympy.physics.quantum import TensorProduct as kron

# Circuit diagrams for larger QPUs are very wide images generated by this app.
PIL.Image.MAX_IMAGE_PIXELS = None

st.set_page_config(
    page_title="Ket compilation example",
    page_icon=":material/device_hub:",
    layout="wide",
)

# ── Sympy gate matrices (same conventions as the Qiskit gates ket emits) ───────
I_mat = eye(2)
sp_X = Matrix([[0, 1], [1, 0]])
sp_Y = Matrix([[0, -I], [I, 0]])


def Rx(t):
    return cos(t / 2) * I_mat - I * sin(t / 2) * sp_X


def Rz(t):
    return Matrix([[exp(-I * t / 2), 0], [0, exp(I * t / 2)]])


def Rzz(t):
    return sp.diag(exp(-I * t / 2), exp(I * t / 2), exp(I * t / 2), exp(-I * t / 2))


def GPi(p):
    return Matrix([[0, exp(-I * p)], [exp(I * p), 0]])


def GPi2(p):
    return Matrix([[1, -I * exp(-I * p)], [-I * exp(I * p), 1]]) / sp.sqrt(2)


sp_SX = sp.Rational(1, 2) * Matrix([[1 + I, 1 - I], [1 - I, 1 + I]])
sp_iSWAP = Matrix([[1, 0, 0, 0], [0, 0, I, 0], [0, I, 0, 0], [0, 0, 0, 1]])
sp_CZ = sp.diag(1, 1, 1, -1)
sp_ECR = Matrix([[0, 1, 0, I], [1, 0, -I, 0], [0, I, 0, 1], [-I, 0, 1, 0]]) / sp.sqrt(2)
sp_MS = (eye(4) - I * kron(sp_X, sp_X)) / sp.sqrt(2)

theta_sym, phi_sym = sp.symbols("theta phi", real=True)

GATESET_MATRICES = {
    "RzGPiGPi2MS": [
        (r"R_z(\theta)", Rz(theta_sym)),
        (r"GPi(\phi)", GPi(phi_sym)),
        (r"GPi_2(\phi)", GPi2(phi_sym)),
        (r"MS", sp_MS),
    ],
    "RzRxISWAP": [
        (r"R_z(\theta)", Rz(theta_sym)),
        (r"R_x(\theta)", Rx(theta_sym)),
        (r"iSWAP", sp_iSWAP),
    ],
    "RzSXCZ": [
        (r"R_z(\theta)", Rz(theta_sym)),
        (r"\sqrt{X}", sp_SX),
        (r"CZ", sp_CZ),
    ],
    "RzSXECR": [
        (r"R_z(\theta)", Rz(theta_sym)),
        (r"\sqrt{X}", sp_SX),
        (r"ECR", sp_ECR),
    ],
    "RzSXXRzz": [
        (r"R_z(\theta)", Rz(theta_sym)),
        (r"\sqrt{X}", sp_SX),
        (r"X", sp_X),
        (r"R_{zz}(\theta)", Rzz(theta_sym)),
    ],
}


# ── Ket diffusion circuit ──────────────────────────────────────────────────────
def diffusion(qubits: Quant):
    with around(cat(H, X), qubits):
        CZ(*qubits)


def generate_grid_edges(n: int, m: int) -> list[tuple[int, int]]:
    edges = []
    for r in range(n):
        for c in range(m):
            node = r * m + c
            if c < m - 1:
                edges.append((node, node + 1))
            if r < n - 1:
                edges.append((node, node + m))
    return edges


# ── Circuit drawing ────────────────────────────────────────────────────────────
# Streamlit runs each rerun in a new thread. Running ket/Qiskit from many
# short-lived threads crashes the process (segfault in Qiskit's allocator), so
# all compilation goes through one long-lived worker thread.
@st.cache_resource
def _worker() -> ThreadPoolExecutor:
    return ThreadPoolExecutor(max_workers=1, thread_name_prefix="ket")


def _draw_png(**kwargs) -> bytes:
    def job():
        try:
            fig = qulib.draw(diffusion, fold=60, output="mpl", **kwargs)
            buf = io.BytesIO()
            fig.savefig(buf, format="png", bbox_inches="tight")
            plt.close(fig)
            return buf.getvalue()
        finally:
            # Free ket/Qiskit objects on the worker thread too.
            gc.collect()

    return _worker().submit(job).result()


@st.cache_data(show_spinner=False)
def draw_high_level(num_qubits: int) -> bytes:
    return _draw_png(num_qubits=num_qubits)


@st.cache_data(show_spinner=False)
def draw_decomposed(num_qubits: int, qpu_size: int) -> bytes:
    return _draw_png(num_qubits=num_qubits, decompose=True, qpu_size=qpu_size)


@st.cache_data(show_spinner=False)
def draw_mapped(num_qubits: int, qpu_size: int, coupling_graph: tuple) -> bytes:
    return _draw_png(
        num_qubits=num_qubits,
        qpu_size=qpu_size,
        coupling_graph=list(coupling_graph),
    )


@st.cache_data(show_spinner=False)
def draw_native(
    num_qubits: int, qpu_size: int, coupling_graph: tuple, gateset_name: str
) -> bytes:
    return _draw_png(
        num_qubits=num_qubits,
        qpu_size=qpu_size,
        coupling_graph=list(coupling_graph),
        native_gate_set=getattr(gateset, gateset_name)(),
    )


def coupling_graph_figure(grid_n: int, grid_m: int, edges: list[tuple[int, int]]):
    fig, ax = plt.subplots(figsize=(max(2, grid_m), max(2, grid_n)))
    fig.patch.set_alpha(0)
    ax.set_facecolor("none")
    G = nx.Graph()
    G.add_nodes_from(range(grid_n * grid_m))
    G.add_edges_from(edges)
    pos = {r * grid_m + c: (c, -r) for r in range(grid_n) for c in range(grid_m)}
    nx.draw(
        G,
        pos=pos,
        ax=ax,
        with_labels=True,
        node_color="#4F8BF9",
        font_color="white",
        node_size=600,
        font_weight="bold",
        edge_color="#888",
        width=2,
    )
    ax.margins(0.15)
    return fig


# ── Sidebar: all controls ──────────────────────────────────────────────────────
with st.sidebar:
    st.header(":material/tune: Configuration")

    st.subheader("Circuit")
    num_qubits = st.slider("Number of qubits", min_value=2, max_value=7, value=7)

    st.subheader("QPU")
    col_n, col_m = st.columns(2)
    grid_n = int(col_n.number_input("Rows", min_value=1, max_value=10, value=4))
    grid_m = int(col_m.number_input("Columns", min_value=1, max_value=10, value=4))
    qpu_size = grid_n * grid_m
    st.caption(f":material/memory: **{qpu_size} qubits** on the QPU")

    st.subheader("Native gateset")
    selected_gateset = st.selectbox(
        "Gateset",
        list(GATESET_MATRICES.keys()),
        label_visibility="collapsed",
    )

    qpu_fits = qpu_size >= num_qubits
    if not qpu_fits:
        st.warning(
            f"The QPU has only {qpu_size} qubits but the circuit needs "
            f"{num_qubits}. Increase the grid size to compile.",
            icon=":material/warning:",
        )

    st.space("small")
    run_button = st.button(
        ":material/play_arrow: Update circuits",
        type="primary",
        width="stretch",
        disabled=not qpu_fits,
    )

# ── Main area ─────────────────────────────────────────────────────────────────
st.title("Ket compilation example", anchor=False)
st.caption(
    "Follow a Grover diffusion operator through the ket compilation stack: "
    "decomposition, qubit mapping on a grid QPU, and translation to a native gateset."
)

coupling_graph = generate_grid_edges(grid_n, grid_m)

graph_tab, matrices_tab, code_tab = st.tabs(
    [
        ":material/device_hub: QPU coupling graph",
        f":material/calculate: {selected_gateset} matrices",
        ":material/code: Diffusion function",
    ]
)

with graph_tab:
    with st.container(border=True):
        c1, c2, c3 = st.columns(3)
        c1.metric("Physical qubits", qpu_size)
        c2.metric("Couplings", len(coupling_graph))
        c3.metric("Auxiliary qubits", max(qpu_size - num_qubits, 0))
        fig_graph = coupling_graph_figure(grid_n, grid_m, coupling_graph)
        st.pyplot(fig_graph, width="content")
        plt.close(fig_graph)

with matrices_tab:
    with st.container(border=True):
        entries = GATESET_MATRICES[selected_gateset]
        for i in range(0, len(entries), 2):
            cols = st.columns(2)
            for col, (label, mat) in zip(cols, entries[i : i + 2]):
                with col:
                    st.latex(f"{label} = {sp.latex(mat)}")

with code_tab:
    st.code(inspect.getsource(diffusion).strip(), language="python")

st.space("small")

current_config = {
    "num_qubits": num_qubits,
    "grid_n": grid_n,
    "grid_m": grid_m,
    "selected_gateset": selected_gateset,
}

# ── Circuit compilation (triggered by button) ──────────────────────────────────
STAGES = [
    ("high", ":material/bolt:", "High-level"),
    ("dec", ":material/compress:", "Decomposed"),
    ("map", ":material/map:", "Mapped"),
    ("native", ":material/memory:", "Native gates"),
]

if run_button and qpu_fits:
    edges = tuple(coupling_graph)
    jobs = {
        "high": lambda: draw_high_level(num_qubits),
        "dec": lambda: draw_decomposed(num_qubits, qpu_size),
        "map": lambda: draw_mapped(num_qubits, qpu_size, edges),
        "native": lambda: draw_native(num_qubits, qpu_size, edges, selected_gateset),
    }
    results = {"config": current_config, "images": {}, "errors": {}}
    with st.status(":material/sync: Compiling circuits…", expanded=True) as status:
        for key, icon, name in STAGES:
            st.write(f"{icon} {name} circuit…")
            try:
                results["images"][key] = jobs[key]()
            except Exception as e:  # show the error in its tab, keep going
                results["errors"][key] = str(e)

        if results["errors"]:
            status.update(
                label=":material/error: Compilation finished with errors",
                state="error",
                expanded=False,
            )
        else:
            status.update(
                label=":material/check_circle: Compilation complete",
                state="complete",
                expanded=False,
            )

    st.session_state.circuit_results = results
    st.toast("Circuits updated!", icon=":material/check:")

# ── Display stored results ─────────────────────────────────────────────────────
res = st.session_state.get("circuit_results")
if res is None:
    st.info(
        "Configure the parameters in the sidebar and click **Update circuits** to compile.",
        icon=":material/info:",
    )
else:
    if res["config"] != current_config:
        cfg = res["config"]
        st.warning(
            "Settings changed since the last compilation. Showing circuits for "
            f"{cfg['num_qubits']} qubits on a {cfg['grid_n']}×{cfg['grid_m']} QPU "
            f"with {cfg['selected_gateset']}. Click **Update circuits** to refresh.",
            icon=":material/history:",
        )

    tabs = st.tabs([f"{icon} {name}" for _, icon, name in STAGES])
    for tab, (key, _, name) in zip(tabs, STAGES):
        with tab:
            if key in res["errors"]:
                st.error(
                    f"{name} compilation failed: {res['errors'][key]}",
                    icon=":material/error:",
                )
            elif key in res["images"]:
                st.download_button(
                    ":material/download: Download PNG",
                    data=res["images"][key],
                    file_name=f"diffusion_{key}.png",
                    mime="image/png",
                    key=f"download_{key}",
                )
                st.image(res["images"][key])
